export const envelope = [160, 26, 32];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;

  // ---------------------------------------------------------
  // 1. PALETTE RESOLUTION & BLOCK STATE HELPERS
  // ---------------------------------------------------------
  const stonePrimary = api.theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone?.accent || "minecraft:cracked_stone_bricks";
  const stoneStairs = api.theme.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone?.wall || "minecraft:stone_brick_wall";

  const groundPave = api.theme.ground?.pavement || "minecraft:cobblestone";
  const groundKerb = api.theme.ground?.kerb || "minecraft:stone";
  const groundPlinth = api.theme.ground?.plinth || "minecraft:deepslate_bricks";

  const woodPlanks = api.theme.wood?.planks || "minecraft:oak_planks";
  const woodLog = api.theme.wood?.log || "minecraft:oak_log";
  const woodStripped = api.theme.wood?.stripped || "minecraft:stripped_oak_log";
  const woodStairs = api.theme.wood?.stairs || "minecraft:oak_stairs";
  const woodSlab = api.theme.wood?.slab || "minecraft:oak_slab";
  const woodFence = api.theme.wood?.fence || "minecraft:oak_fence";
  const woodTrapdoor = api.theme.wood?.trapdoor || "minecraft:oak_trapdoor";

  function cleanId(block) {
    return block.split("[")[0];
  }

  function getLog(block, axis = "y") {
    return `${cleanId(block)}[axis=${axis}]`;
  }

  function getStairs(block, facing = "north", half = "bottom", shape = "straight") {
    return `${cleanId(block)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function getSlab(block, type = "bottom") {
    return `${cleanId(block)}[type=${type}]`;
  }

  function getTrapdoor(block, facing = "north", half = "bottom", open = false) {
    return `${cleanId(block)}[facing=${facing},half=${half},open=${open}]`;
  }

  function getLadder(facing = "north") {
    return `minecraft:ladder[facing=${facing}]`;
  }

  function setB(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function fillBox(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.max(0, Math.min(x1, x2));
    const maxX = Math.min(W - 1, Math.max(x1, x2));
    const minY = Math.max(0, Math.min(y1, y2));
    const maxY = Math.min(H - 1, Math.max(y1, y2));
    const minZ = Math.max(0, Math.min(z1, z2));
    const maxZ = Math.min(D - 1, Math.max(z1, z2));
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  function getStoneVariation(x, y, z) {
    const val = Math.abs((Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453) % 1);
    if (val < 0.55) return stonePrimary;
    if (val < 0.85) return stoneAccent;
    return groundPave;
  }

  // ---------------------------------------------------------
  // 2. TERRAIN CONFORMANCE & RIVERBED FOUNDATION
  // ---------------------------------------------------------
  function getGroundY(x, z) {
    const h = Math.round(api.heightAt(x, z));
    return Math.max(0, Math.min(seatY + h, 14));
  }

  function buildFoundationColumn(x, z, topY, fillBlock) {
    const gy = getGroundY(x, z);
    for (let y = gy; y <= topY; y++) {
      if (y === gy) {
        setB(x, y, z, groundPlinth);
      } else {
        setB(x, y, z, fillBlock || getStoneVariation(x, y, z));
      }
    }
    // Skirt down to envelope base if terrain fell below 0
    for (let y = 0; y < gy; y++) {
      setB(x, y, z, groundPlinth);
    }
  }

  // Continuous submerged rock foundation & riverbed causeway (guarantees 1 connected solid)
  for (let x = 0; x < W; x++) {
    for (let z = 10; z <= 22; z++) {
      buildFoundationColumn(x, z, 5, groundPlinth);
    }
  }

  // ---------------------------------------------------------
  // 3. PIER GEOMETRY & CUTWATERS (STARLINGS)
  // ---------------------------------------------------------
  const piers = [
    { cx: 47, name: "Pier 1 (West Complete)", halfBuilt: false },
    { cx: 81, name: "Pier 2 (West Construction Head)", halfBuilt: false },
    { cx: 115, name: "Pier 3 (East Under Construction)", halfBuilt: true }
  ];

  function buildPier(pier) {
    const cx = pier.cx;
    const minX = cx - 5;
    const maxX = cx + 5;
    const topY = pier.halfBuilt ? 17 : 19;

    // Main rectangular pier shaft
    for (let x = minX; x <= maxX; x++) {
      for (let z = 10; z <= 22; z++) {
        buildFoundationColumn(x, z, topY, getStoneVariation(x, 5, z));
        for (let y = 6; y <= topY; y++) {
          setB(x, y, z, getStoneVariation(x, y, z));
        }
      }
    }

    // Triangular Cutwaters (Upstream - North, Downstream - South)
    // North cutwater: Z from 5 to 9, apex at (cx, 5)
    for (let z = 5; z <= 9; z++) {
      const spanW = z - 5;
      for (let x = cx - spanW; x <= cx + spanW; x++) {
        buildFoundationColumn(x, z, 14, getStoneVariation(x, 5, z));
        for (let y = 6; y <= 12; y++) {
          setB(x, y, z, getStoneVariation(x, y, z));
        }
        // Sloped cutwater cap (Y=13..14)
        if (z === 5) {
          setB(x, 13, z, getStairs(stoneStairs, "south", "bottom"));
          setB(x, 14, z, getSlab(stoneSlab, "bottom"));
        } else if (x === cx - spanW) {
          setB(x, 13, z, getStairs(stoneStairs, "west", "bottom"));
        } else if (x === cx + spanW) {
          setB(x, 13, z, getStairs(stoneStairs, "east", "bottom"));
        } else {
          setB(x, 13, z, getStoneVariation(x, 13, z));
          setB(x, 14, z, getSlab(stoneSlab, "bottom"));
        }
      }
    }

    // South cutwater: Z from 23 to 27, apex at (cx, 27)
    for (let z = 23; z <= 27; z++) {
      const spanW = 27 - z;
      for (let x = cx - spanW; x <= cx + spanW; x++) {
        buildFoundationColumn(x, z, 14, getStoneVariation(x, 5, z));
        for (let y = 6; y <= 12; y++) {
          setB(x, y, z, getStoneVariation(x, y, z));
        }
        // Sloped cutwater cap (Y=13..14)
        if (z === 27) {
          setB(x, 13, z, getStairs(stoneStairs, "north", "bottom"));
          setB(x, 14, z, getSlab(stoneSlab, "bottom"));
        } else if (x === cx - spanW) {
          setB(x, 13, z, getStairs(stoneStairs, "west", "bottom"));
        } else if (x === cx + spanW) {
          setB(x, 13, z, getStairs(stoneStairs, "east", "bottom"));
        } else {
          setB(x, 13, z, getStoneVariation(x, 13, z));
          setB(x, 14, z, getSlab(stoneSlab, "bottom"));
        }
      }
    }

    // Pier Pilasters and Deck Refuges (for complete piers)
    if (!pier.halfBuilt) {
      // Pilasters rising to deck level
      for (let y = 14; y <= 18; y++) {
        setB(cx, y, 9, getStoneVariation(cx, y, 9));
        setB(cx, y, 23, getStoneVariation(cx, y, 23));
      }
      // Corbelled refuge bays at Y=18
      for (let dx = -1; dx <= 1; dx++) {
        setB(cx + dx, 18, 9, getStairs(stoneStairs, "south", "top"));
        setB(cx + dx, 18, 23, getStairs(stoneStairs, "north", "top"));
      }
      // Refuge floors & parapet at Y=19..21
      for (let dx = -1; dx <= 1; dx++) {
        setB(cx + dx, 19, 9, groundPave);
        setB(cx + dx, 19, 23, groundPave);
        setB(cx + dx, 20, 8, stoneWall);
        setB(cx + dx, 20, 24, stoneWall);
      }
      setB(cx - 2, 20, 9, stoneWall);
      setB(cx + 2, 20, 9, stoneWall);
      setB(cx - 2, 20, 23, stoneWall);
      setB(cx + 2, 20, 23, stoneWall);
    }
  }

  piers.forEach(buildPier);

  // ---------------------------------------------------------
  // 4. ARCHES & SPANDRELS
  // ---------------------------------------------------------
  function buildArch(startX, endX, brokenSide = null) {
    const midX = (startX + endX) / 2;
    const spanRadius = (endX - startX) / 2;
    const springY = 9;
    const archH = 8;

    for (let x = startX; x <= endX; x++) {
      const norm = (x - midX) / spanRadius;
      if (Math.abs(norm) > 1.0) continue;
      const curve = Math.sqrt(Math.max(0, 1 - norm * norm));
      const underY = Math.round(springY + archH * curve);
      const ringTopY = underY + 1;

      // Handle the incomplete / broken arch (Span 3)
      if (brokenSide === "broken_mid") {
        const breakX_West = 94 + (Math.abs(x * 7) % 3);
        const startX_East = 106;

        if (x > breakX_West && x < startX_East) {
          // Central open gap in stone masonry
          continue;
        }

        if (x >= startX_East) {
          // East incomplete arch: Place arch stones only near pier spring
          for (let z = 11; z <= 21; z++) {
            setB(x, underY, z, getStoneVariation(x, underY, z));
            setB(x, ringTopY, z, getStoneVariation(x, ringTopY, z));
          }
          continue;
        }

        // West breaking end
        if (x === breakX_West) {
          for (let z = 11; z <= 21; z++) {
            if ((z + x) % 2 === 0) {
              setB(x, underY, z, stoneAccent);
              // Protruding broken timber falsework log
              setB(x, underY - 1, z, getLog(woodLog, "x"));
            }
          }
          continue;
        }
      }

      // Solid Arch Ring (Voussoirs)
      for (let z = 11; z <= 21; z++) {
        setB(x, underY, z, getStoneVariation(x, underY, z));
        setB(x, ringTopY, z, getStoneVariation(x, ringTopY, z));

        // Fill spandrels up to road deck bottom (Y=18)
        for (let y = ringTopY + 1; y <= 18; y++) {
          if (z === 11 || z === 21) {
            setB(x, y, z, getStoneVariation(x, y, z));
          } else {
            setB(x, y, z, (y === 18) ? groundKerb : stoneAccent);
          }
        }
      }
    }
  }

  // Span 1: West Land/River Arch (X: 18 to 42)
  buildArch(18, 42);

  // Span 2: West River Arch (X: 52 to 76)
  buildArch(52, 76);

  // Span 3: Broken Mid-River Arch (X: 86 to 110)
  buildArch(86, 110, "broken_mid");

  // Span 4: East River Arch (X: 120 to 142)
  buildArch(120, 142);

  // ---------------------------------------------------------
  // 5. ROAD DECK, PAVEMENT & PARAPETS
  // ---------------------------------------------------------
  // West Deck (X: 0 to 92)
  for (let x = 0; x <= 92; x++) {
    for (let z = 12; z <= 20; z++) {
      if (z === 12 || z === 20) {
        setB(x, 19, z, groundKerb);
      } else {
        const val = Math.abs((Math.sin(x * 3.1 + z * 7.7) * 1000) % 1);
        setB(x, 19, z, val < 0.7 ? groundPave : stonePrimary);
      }
    }
    // Parapets on West section
    setB(x, 20, 11, stonePrimary);
    setB(x, 21, 11, stoneWall);
    setB(x, 20, 21, stonePrimary);
    setB(x, 21, 21, stoneWall);
  }

  // West Deck End Barricade & Construction Warning (X: 91..92)
  for (let z = 12; z <= 20; z++) {
    setB(92, 20, z, getLog(woodStripped, "z"));
    setB(92, 21, z, woodFence);
  }
  setB(92, 22, 13, "minecraft:campfire[lit=true]");
  setB(92, 22, 19, "minecraft:campfire[lit=true]");

  // Stacks of dressed cut-stone on West deck (X: 88..90)
  fillBox(88, 20, 13, 90, 21, 15, stonePrimary);
  fillBox(89, 20, 17, 91, 20, 18, stoneAccent);

  // East Deck (X: 112 to 159)
  for (let x = 112; x <= 159; x++) {
    for (let z = 12; z <= 20; z++) {
      if (z === 12 || z === 20) {
        setB(x, 19, z, groundKerb);
      } else {
        const val = Math.abs((Math.sin(x * 3.1 + z * 7.7) * 1000) % 1);
        setB(x, 19, z, val < 0.7 ? groundPave : stonePrimary);
      }
    }
    // Parapets on East section
    if (x >= 118) {
      setB(x, 20, 11, stonePrimary);
      setB(x, 21, 11, stoneWall);
      setB(x, 20, 21, stonePrimary);
      setB(x, 21, 21, stoneWall);
    }
  }

  // East Deck Construction Staging (X: 112..117)
  fillBox(113, 20, 13, 115, 21, 14, stonePrimary);
  setB(116, 20, 17, "minecraft:cauldron");
  setB(116, 20, 18, woodFence);
  setB(116, 21, 18, "minecraft:lantern[hanging=false]");

  // ---------------------------------------------------------
  // 6. TIMBER CATWALK & FALSEWORK CENTERING IN CENTRAL GAP
  // ---------------------------------------------------------
  // Suspended maintenance / construction plankway spanning X: 86 to 112
  for (let x = 86; x <= 112; x++) {
    for (let z = 15; z <= 17; z++) {
      setB(x, 9, z, woodPlanks);
    }
    // Handrails & Hangers
    setB(x, 10, 15, woodFence);
    setB(x, 10, 17, woodFence);
    if (x % 4 === 0) {
      setB(x, 8, 16, getLog(woodLog, "z"));
      setB(x, 8, 15, woodFence);
      setB(x, 8, 17, woodFence);
    }
  }

  // Timber falsework centering trusses under East incomplete arch (X: 104 to 110)
  for (let x = 104; x <= 110; x++) {
    const norm = (x - 98) / 12;
    const curve = Math.sqrt(Math.max(0, 1 - norm * norm));
    const archUnderside = Math.round(9 + 8 * curve);

    for (let z = 12; z <= 20; z += 4) {
      // Curved wooden falsework rib
      setB(x, archUnderside - 1, z, woodPlanks);
      // Vertical supporting timber struts
      for (let y = 10; y < archUnderside - 1; y++) {
        setB(x, y, z, woodFence);
      }
    }
  }

  // ---------------------------------------------------------
  // 7. BLOCK-AND-TACKLE CRANES & DERRICKS
  // ---------------------------------------------------------
  // Crane 1: Heavy Derrick on Pier 2 (West construction head, X: 88..97)
  // Base sill
  fillBox(87, 20, 15, 89, 20, 17, getLog(woodStripped, "x"));
  // Vertical Mast
  for (let y = 20; y <= 25; y++) {
    setB(88, y, 16, getLog(woodLog, "y"));
  }
  // Horizontal Boom extending East over the chasm
  for (let x = 88; x <= 96; x++) {
    setB(x, 25, 16, getLog(woodLog, "x"));
  }
  // Diagonal Strut
  setB(90, 21, 16, getStairs(woodStairs, "west", "bottom"));
  setB(91, 22, 16, woodPlanks);
  setB(92, 23, 16, woodPlanks);
  setB(93, 24, 16, getStairs(woodStairs, "east", "top"));
  // Winch spool at base
  setB(87, 21, 16, getTrapdoor(woodTrapdoor, "west", "bottom", false));
  setB(89, 21, 16, getTrapdoor(woodTrapdoor, "east", "bottom", false));
  // Suspended Block & Tackle Chain with Ashlar Stone
  for (let y = 18; y <= 24; y++) {
    setB(96, y, 16, "minecraft:chain[axis=y]");
  }
  setB(96, 17, 16, stonePrimary);
  setB(95, 17, 16, stonePrimary);
  setB(96, 16, 16, getSlab(stoneSlab, "bottom"));
  setB(95, 16, 16, getSlab(stoneSlab, "bottom"));

  // Crane 2: A-Frame Hoist & Scaffolding Cage on Pier 3 (East, X: 110..120)
  // Multi-story Scaffolding Framework around Pier 3
  const scaffoldPosts = [
    [109, 8], [109, 24],
    [115, 8], [115, 24],
    [121, 8], [121, 24]
  ];

  scaffoldPosts.forEach(([sx, sz]) => {
    buildFoundationColumn(sx, sz, 22, getLog(woodLog, "y"));
    for (let y = 6; y <= 22; y++) {
      setB(sx, y, sz, getLog(woodLog, "y"));
    }
  });

  // Scaffolding horizontal ledger poles & platforms at Y=11, 15, 19
  [11, 15, 19].forEach((sy) => {
    // North ledgers
    for (let x = 109; x <= 121; x++) {
      setB(x, sy, 8, getLog(woodLog, "x"));
      setB(x, sy, 9, woodPlanks);
      setB(x, sy + 1, 8, woodFence);
    }
    // South ledgers
    for (let x = 109; x <= 121; x++) {
      setB(x, sy, 24, getLog(woodLog, "x"));
      setB(x, sy, 23, woodPlanks);
      setB(x, sy + 1, 24, woodFence);
    }
  });

  // Ladder access on North scaffold post
  for (let y = 6; y <= 22; y++) {
    setB(121, y, 9, getLadder("north"));
  }

  // A-Frame Crane atop Pier 3 (X: 114..118, Y: 18..25)
  for (let y = 18; y <= 24; y++) {
    setB(116, y, 14, getLog(woodLog, "y"));
    setB(116, y, 18, getLog(woodLog, "y"));
  }
  fillBox(116, 24, 14, 116, 24, 18, getLog(woodLog, "z"));
  // Crane boom pointing West
  for (let x = 107; x <= 116; x++) {
    setB(x, 24, 16, getLog(woodLog, "x"));
  }
  // Counterweight box at rear (X: 118)
  fillBox(117, 18, 15, 119, 20, 17, groundPave);
  // Suspended tackle & stone block on Pier 3 crane
  for (let y = 18; y <= 23; y++) {
    setB(107, y, 16, "minecraft:chain[axis=y]");
  }
  setB(107, 17, 16, stonePrimary);

  // ---------------------------------------------------------
  // 8. FORTIFIED BRIDGEHEAD GATEHOUSES & ABUTMENTS
  // ---------------------------------------------------------
  // Helper to build bridgehead gatehouse fortress
  function buildBridgehead(startX, endX, isWest) {
    const minX = Math.min(startX, endX);
    const maxX = Math.max(startX, endX);

    // Foundation & Solid Mass
    for (let x = minX; x <= maxX; x++) {
      for (let z = 8; z <= 24; z++) {
        buildFoundationColumn(x, z, 18, getStoneVariation(x, 5, z));
      }
    }

    // Riverbank Towpath Vault Tunnel (through abutment at Y=6..10)
    const tunnelX = isWest ? 11 : 147;
    for (let x = tunnelX - 2; x <= tunnelX + 2; x++) {
      for (let z = 8; z <= 24; z++) {
        for (let y = 6; y <= 10; y++) {
          setB(x, y, z, "minecraft:air");
        }
        setB(x, 11, z, getStoneVariation(x, 11, z));
      }
    }

    // Approach Ramp (from fort bank onto bridge deck)
    const rampStart = isWest ? 0 : 159;
    const rampEnd = isWest ? 7 : 152;
    const stepDir = isWest ? 1 : -1;
    let currY = 15;
    for (let x = rampStart; x !== rampEnd + stepDir; x += stepDir) {
      for (let z = 12; z <= 20; z++) {
        for (let y = currY; y <= 19; y++) {
          setB(x, y, z, (y === 19) ? groundPave : stonePrimary);
        }
      }
      if (currY < 19) currY++;
    }

    // Flanking Guard Bastion Turrets
    // North Turret (Z: 8..11), South Turret (Z: 21..24)
    const tMinX = isWest ? 3 : 152;
    const tMaxX = isWest ? 7 : 156;

    [ [8, 11], [21, 24] ].forEach(([tz1, tz2]) => {
      for (let x = tMinX; x <= tMaxX; x++) {
        for (let z = tz1; z <= tz2; z++) {
          for (let y = 18; y <= 24; y++) {
            setB(x, y, z, getStoneVariation(x, y, z));
          }
        }
      }
      // Crenellations & Braziers on turret roof (Y=25)
      for (let x = tMinX; x <= tMaxX; x++) {
        for (let z = tz1; z <= tz2; z++) {
          const isEdge = (x === tMinX || x === tMaxX || z === tz1 || z === tz2);
          if (isEdge && (x + z) % 2 === 0) {
            setB(x, 25, z, stoneWall);
          }
        }
      }
      setB(Math.floor((tMinX + tMaxX) / 2), 25, Math.floor((tz1 + tz2) / 2), "minecraft:campfire[lit=true]");
    });

    // Fortified Gate Arch spanning road between turrets
    const archX = isWest ? 5 : 154;
    for (let z = 12; z <= 20; z++) {
      for (let y = 20; y <= 24; y++) {
        if (z === 12 || z === 20 || y === 24) {
          setB(archX, y, z, stonePrimary);
        } else {
          setB(archX, y, z, "minecraft:air");
        }
      }
      // Machicolation corbels above arch
      setB(archX, 25, z, getStairs(stoneStairs, isWest ? "east" : "west", "top"));
    }

    // Interior Chamber (hollow room inside the abutment for furnishing)
    const roomMinX = isWest ? 3 : 152;
    const roomMaxX = isWest ? 7 : 156;
    for (let x = roomMinX; x <= roomMaxX; x++) {
      for (let z = 12; z <= 20; z++) {
        for (let y = 8; y <= 12; y++) {
          setB(x, y, z, "minecraft:air");
        }
        setB(x, 7, z, groundKerb);     // Solid Floor
        setB(x, 13, z, stonePrimary);   // Solid Ceiling
      }
    }
    // Doorway into the interior from towpath tunnel
    const doorX = isWest ? 7 : 152;
    for (let y = 8; y <= 10; y++) {
      setB(doorX, y, 16, "minecraft:air");
    }
  }

  // West Fort Bridgehead (Fort Alpha)
  buildBridgehead(0, 18, true);

  // East Fort Bridgehead (Fort Beta)
  buildBridgehead(142, 159, false);

  // Pier 1 Interior Vault (Bridge Chapel / Guard Vault)
  for (let x = 44; x <= 50; x++) {
    for (let z = 13; z <= 19; z++) {
      for (let y = 8; y <= 12; y++) {
        setB(x, y, z, "minecraft:air");
      }
      setB(x, 7, z, groundKerb);     // Floor
      setB(x, 13, z, stonePrimary);   // Ceiling
    }
  }
  // Doorway into Pier 1 Vault from North cutwater
  setB(47, 8, 12, "minecraft:air");
  setB(47, 9, 12, "minecraft:air");
  setB(47, 10, 12, getStairs(stoneStairs, "south", "bottom"));

  // ---------------------------------------------------------
  // 9. RETURN SPECIFICATION & ANCHORS
  // ---------------------------------------------------------
  return {
    name: "half_built_bridge",
    seatY: seatY,
    anchors: {
      front: [80, 20, 0],              // Looking North across the river
      west_gate: [0, 19, 16],          // West Fort entrance
      east_gate: [159, 19, 16],        // East Fort entrance
      mid_chasm: [96, 20, 16]          // Edge of broken bridge deck
    },
    interiors: [
      {
        min: [3, 8, 12],
        max: [7, 12, 20],
        kind: "quarters"
      },
      {
        min: [44, 8, 13],
        max: [50, 12, 19],
        kind: "vault"
      },
      {
        min: [152, 8, 12],
        max: [156, 12, 20],
        kind: "armoury"
      }
    ]
  };
}

