export const envelope = [9, 12, 9];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;
  const deckY = 4;
  const idx = api.instance.index;
  const variant = idx % 6;

  // Safe setter bounded strictly to envelope
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Helper to format block states cleanly with theme fallbacks
  function withState(block, states) {
    const base = block.split("[")[0];
    const entries = Object.entries(states).map(([k, v]) => `${k}=${v}`).join(",");
    return `${base}[${entries}]`;
  }

  // Theme resolution with robust fallbacks
  const themeWood = api.theme?.wood || {};
  const themeStone = api.theme?.stone || {};
  const themeGround = api.theme?.ground || {};

  const woodPlanks = themeWood.planks || "minecraft:oak_planks";
  const woodLog = themeWood.log || "minecraft:oak_log";
  const woodStripped = themeWood.stripped || "minecraft:stripped_oak_log";
  const woodStairs = themeWood.stairs || "minecraft:oak_stairs";
  const woodSlab = themeWood.slab || "minecraft:oak_slab";
  const woodFence = themeWood.fence || "minecraft:oak_fence";
  const woodTrapdoor = themeWood.trapdoor || "minecraft:oak_trapdoor";

  const stonePrimary = themeStone.primary || "minecraft:stone_bricks";
  const stoneAccent = themeStone.accent || "minecraft:mossy_stone_bricks";
  const stoneStairs = themeStone.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = themeStone.slab || "minecraft:stone_brick_slab";
  const stoneWall = themeStone.wall || "minecraft:stone_brick_wall";

  const groundPlinth = themeGround.plinth || stonePrimary;

  // Ground conformity: calculate node-local ground Y at column (x, z)
  function getGroundY(x, z) {
    const h = api.heightAt(x, z);
    return Math.max(0, Math.min(seatY + h, H - 1));
  }

  // ==========================================
  // 1. SOLID FOUNDATION (CONFORMS TO TERRAIN)
  // ==========================================
  // Main 7x7 platform footprint (x: 1..7, z: 1..7)
  for (let x = 1; x <= 7; x++) {
    for (let z = 1; z <= 7; z++) {
      const gY = Math.min(getGroundY(x, z), deckY);
      for (let y = gY; y < deckY; y++) {
        const isPlinth = (y === gY);
        const isAccent = ((x * 3 + y * 5 + z * 7 + idx) % 4 === 0);
        const blk = isPlinth ? groundPlinth : (isAccent ? stoneAccent : stonePrimary);
        setBlock(x, y, z, blk);
      }
    }
  }

  // Corner & side buttress piers down to terrain
  const buttresses = [
    [0, 1], [0, 7], [8, 1], [8, 7],
    [1, 0], [7, 0], [1, 8], [7, 8],
    [0, 4], [8, 4], [4, 0]
  ];
  for (const [bx, bz] of buttresses) {
    const gY = Math.min(getGroundY(bx, bz), deckY - 1);
    for (let y = gY; y <= deckY - 1; y++) {
      const isPlinth = (y === gY);
      const isAccent = ((bx + y + bz + idx) % 3 === 0);
      setBlock(bx, y, bz, isPlinth ? groundPlinth : (isAccent ? stoneAccent : stonePrimary));
    }
  }

  // Stepped footing stairs meeting ground at outer edges
  const gWest = Math.min(getGroundY(0, 4), deckY - 2);
  setBlock(0, gWest, 4, withState(stoneStairs, { facing: "west", half: "bottom" }));
  const gEast = Math.min(getGroundY(8, 4), deckY - 2);
  setBlock(8, gEast, 4, withState(stoneStairs, { facing: "east", half: "bottom" }));
  const gNorth = Math.min(getGroundY(4, 0), deckY - 2);
  setBlock(4, gNorth, 0, withState(stoneStairs, { facing: "north", half: "bottom" }));

  // ==========================================
  // 2. TIMBER & STONE DECK (y = deckY = 4)
  // ==========================================
  for (let x = 1; x <= 7; x++) {
    for (let z = 1; z <= 7; z++) {
      const isPerimeter = (x === 1 || x === 7 || z === 1 || z === 7);
      if (isPerimeter) {
        const isAccent = ((x * 2 + z * 3 + idx) % 5 === 0);
        setBlock(x, deckY, z, isAccent ? stoneAccent : stonePrimary);
      } else {
        setBlock(x, deckY, z, woodPlanks);
      }
    }
  }
  // Swivel turntable base ring
  setBlock(4, deckY, 4, withState(woodStripped, { axis: "y" }));

  // Rear access stairs (z = 8, x = 3..5)
  for (let x = 3; x <= 5; x++) {
    const gY = Math.min(getGroundY(x, 8), deckY);
    for (let y = gY; y < deckY - 1; y++) {
      setBlock(x, y, 8, stonePrimary);
    }
    if (deckY - 1 >= gY) {
      setBlock(x, deckY - 1, 8, withState(stoneStairs, { facing: "south", half: "bottom" }));
    }
  }

  // ==========================================
  // 3. DEFENSIVE RAMPARTS & PARAPETS
  // ==========================================
  // Heavy corner timber pilasters
  const cornerCols = [[1, 1], [7, 1], [1, 7], [7, 7]];
  for (const [cx, cz] of cornerCols) {
    setBlock(cx, 5, cz, withState(woodLog, { axis: "y" }));
    setBlock(cx, 6, cz, withState(woodLog, { axis: "y" }));
  }

  // Front rampart facing river (z = 1)
  setBlock(2, 5, 1, stoneWall);
  setBlock(3, 5, 1, withState(stoneStairs, { facing: "north", half: "bottom" }));
  setBlock(4, 5, 1, withState(stoneSlab, { type: "bottom" })); // Central firing embrasure
  setBlock(5, 5, 1, withState(stoneStairs, { facing: "north", half: "bottom" }));
  setBlock(6, 5, 1, stoneWall);

  // Front merlons & mantlets (y = 6)
  setBlock(2, 6, 1, withState(woodTrapdoor, { facing: "north", half: "bottom", open: "false" }));
  setBlock(6, 6, 1, withState(woodTrapdoor, { facing: "north", half: "bottom", open: "false" }));

  // Side parapets
  for (let z = 2; z <= 6; z++) {
    setBlock(1, 5, z, (z % 2 === 0) ? stoneWall : woodFence);
    setBlock(7, 5, z, (z % 2 === 0) ? stoneWall : woodFence);
  }

  // Rear rampart wings
  setBlock(2, 5, 7, stoneWall);
  setBlock(6, 5, 7, stoneWall);

  // ==========================================
  // 4. THE WAR BALLISTA (6 UNIQUE INSTANCES)
  // ==========================================
  // Turntable mount (y = 5)
  setBlock(4, 5, 4, withState(woodStripped, { axis: "y" }));
  setBlock(3, 5, 4, withState(woodStairs, { facing: "east", half: "bottom" }));
  setBlock(5, 5, 4, withState(woodStairs, { facing: "west", half: "bottom" }));
  setBlock(4, 5, 5, withState(woodStairs, { facing: "north", half: "bottom" }));
  setBlock(4, 5, 3, withState(woodStairs, { facing: "south", half: "bottom" }));

  if (variant === 0) {
    // -----------------------------------------------------------------
    // VARIANT 0: "FORT ALPHA HEAVY FLAME-BALLISTA"
    // Dual heavy torsion bundles, roaring pitch bolt aimed across river
    // -----------------------------------------------------------------
    // Ballista chassis (y = 6)
    setBlock(4, 6, 5, withState(woodLog, { axis: "x" }));
    setBlock(3, 6, 5, "minecraft:grindstone[face=floor,facing=west]");
    setBlock(5, 6, 5, "minecraft:grindstone[face=floor,facing=east]");
    setBlock(4, 6, 4, withState(woodStripped, { axis: "z" }));
    setBlock(4, 6, 3, withState(woodStripped, { axis: "z" }));
    setBlock(4, 6, 2, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 1, withState(woodStairs, { facing: "north", half: "top" }));

    // Heavy torsion towers & bow prods
    setBlock(3, 6, 3, withState(woodLog, { axis: "y" }));
    setBlock(5, 6, 3, withState(woodLog, { axis: "y" }));
    setBlock(3, 7, 3, withState(woodLog, { axis: "y" }));
    setBlock(5, 7, 3, withState(woodLog, { axis: "y" }));
    setBlock(4, 7, 3, withState(woodSlab, { type: "top" }));

    // Bow prods swept back
    setBlock(2, 6, 2, withState(woodStairs, { facing: "east", half: "bottom" }));
    setBlock(1, 6, 2, woodFence);
    setBlock(0, 6, 3, woodFence);
    setBlock(6, 6, 2, withState(woodStairs, { facing: "west", half: "bottom" }));
    setBlock(7, 6, 2, woodFence);
    setBlock(8, 6, 3, woodFence);

    // Tensioned cord
    setBlock(1, 6, 3, "minecraft:chain[axis=z]");
    setBlock(2, 6, 4, "minecraft:chain[axis=x]");
    setBlock(3, 6, 5, "minecraft:chain[axis=x]");
    setBlock(5, 6, 5, "minecraft:chain[axis=x]");
    setBlock(6, 6, 4, "minecraft:chain[axis=x]");
    setBlock(7, 6, 3, "minecraft:chain[axis=z]");

    // Loaded flaming war bolt
    setBlock(4, 7, 4, woodFence);
    setBlock(4, 7, 2, woodFence);
    setBlock(4, 7, 1, "minecraft:lightning_rod[facing=north]");
    setBlock(4, 7, 0, "minecraft:campfire[facing=north,lit=true]");

    // Props: Firing brazier, ammo barrels, Alpha war banner
    setBlock(2, 5, 6, stoneWall);
    setBlock(2, 6, 6, "minecraft:campfire[facing=north,lit=true]");
    setBlock(2, 7, 6, "minecraft:iron_bars");

    setBlock(6, 5, 5, "minecraft:barrel[facing=up]");
    setBlock(6, 5, 6, "minecraft:barrel[facing=up]");
    setBlock(7, 5, 5, "minecraft:chest[facing=west]");
    setBlock(6, 6, 6, withState(woodTrapdoor, { facing: "north", half: "bottom", open: "false" }));

    setBlock(7, 7, 1, woodFence);
    setBlock(7, 8, 1, woodFence);
    setBlock(7, 8, 0, "minecraft:red_wool");

  } else if (variant === 1) {
    // -----------------------------------------------------------------
    // VARIANT 1: "FORT BETA RIVER HARPOONER"
    // High-angle siege harpoon with trailing chain cable, soul flame
    // -----------------------------------------------------------------
    // Elevated carriage
    setBlock(4, 6, 5, withState(woodLog, { axis: "x" }));
    setBlock(3, 6, 5, woodFence);
    setBlock(5, 6, 5, woodFence);
    setBlock(4, 6, 4, withState(woodStairs, { facing: "north", half: "bottom" }));
    setBlock(4, 7, 3, withState(woodLog, { axis: "z" }));
    setBlock(4, 7, 2, withState(woodLog, { axis: "z" }));
    setBlock(4, 7, 1, withState(woodStairs, { facing: "north", half: "top" }));

    // Torsion prods at elevation
    setBlock(3, 7, 2, withState(woodLog, { axis: "y" }));
    setBlock(5, 7, 2, withState(woodLog, { axis: "y" }));
    setBlock(3, 8, 2, withState(woodLog, { axis: "y" }));
    setBlock(5, 8, 2, withState(woodLog, { axis: "y" }));
    setBlock(4, 8, 2, withState(woodSlab, { type: "bottom" }));

    setBlock(2, 7, 2, withState(woodStairs, { facing: "east", half: "bottom" }));
    setBlock(1, 7, 1, woodFence);
    setBlock(0, 7, 2, woodFence);
    setBlock(6, 7, 2, withState(woodStairs, { facing: "west", half: "bottom" }));
    setBlock(7, 7, 1, woodFence);
    setBlock(8, 7, 2, woodFence);

    // Heavy barbed harpoon with trailing chain
    setBlock(4, 8, 4, "minecraft:chain[axis=z]");
    setBlock(4, 8, 3, "minecraft:chain[axis=z]");
    setBlock(4, 8, 1, "minecraft:iron_bars");
    setBlock(4, 8, 0, "minecraft:anvil[facing=north]");

    // Props: Soul cauldron, cable spool, Beta banner
    setBlock(2, 5, 5, "minecraft:cauldron");
    setBlock(2, 6, 5, "minecraft:soul_campfire[facing=north,lit=true]");

    setBlock(6, 5, 5, "minecraft:barrel[facing=up]");
    setBlock(6, 5, 6, "minecraft:chain[axis=y]");
    setBlock(7, 5, 5, "minecraft:chest[facing=west]");

    setBlock(1, 7, 7, woodFence);
    setBlock(1, 8, 7, woodFence);
    setBlock(1, 9, 7, woodFence);
    setBlock(1, 9, 6, "minecraft:blue_wool");

  } else if (variant === 2) {
    // -----------------------------------------------------------------
    // VARIANT 2: "TWIN-PROD RAPID SCORPION"
    // Dual tiered spring prods, multiple steel bolts, weapon rack
    // -----------------------------------------------------------------
    setBlock(4, 6, 5, withState(woodStripped, { axis: "x" }));
    setBlock(3, 6, 5, "minecraft:grindstone[face=floor,facing=west]");
    setBlock(5, 6, 5, "minecraft:grindstone[face=floor,facing=east]");
    setBlock(4, 6, 4, withState(woodStripped, { axis: "z" }));
    setBlock(4, 6, 3, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 2, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 1, withState(woodStairs, { facing: "north", half: "top" }));

    // Double-deck bow prods
    setBlock(3, 6, 2, withState(woodLog, { axis: "y" }));
    setBlock(5, 6, 2, withState(woodLog, { axis: "y" }));
    setBlock(3, 7, 2, withState(woodLog, { axis: "y" }));
    setBlock(5, 7, 2, withState(woodLog, { axis: "y" }));

    // Lower tier
    setBlock(2, 6, 2, woodFence);
    setBlock(1, 6, 3, woodFence);
    setBlock(6, 6, 2, woodFence);
    setBlock(7, 6, 3, woodFence);
    // Upper tier
    setBlock(2, 7, 2, withState(woodSlab, { type: "bottom" }));
    setBlock(1, 7, 3, withState(woodSlab, { type: "bottom" }));
    setBlock(6, 7, 2, withState(woodSlab, { type: "bottom" }));
    setBlock(7, 7, 3, withState(woodSlab, { type: "bottom" }));

    // Tri-fin war bolt
    setBlock(4, 7, 4, "minecraft:chain[axis=x]");
    setBlock(4, 7, 3, woodFence);
    setBlock(4, 7, 2, woodFence);
    setBlock(4, 7, 1, "minecraft:lightning_rod[facing=north]");
    setBlock(4, 7, 0, "minecraft:iron_bars");

    // Props: Bolt crate, sharpening grindstone, corner brazier
    setBlock(6, 5, 5, woodPlanks);
    setBlock(6, 6, 5, withState(woodTrapdoor, { facing: "north", half: "bottom", open: "false" }));
    setBlock(7, 5, 5, "minecraft:barrel[facing=up]");
    setBlock(2, 5, 4, "minecraft:grindstone[face=floor,facing=north]");
    setBlock(2, 5, 6, stoneWall);
    setBlock(2, 6, 6, "minecraft:campfire[facing=north,lit=true]");

  } else if (variant === 3) {
    // -----------------------------------------------------------------
    // VARIANT 3: "FORTIFIED EMPLACEMENT WITH AMMO HOIST CRANE"
    // Timber gantry crane over the ballista for heavy stone shells
    // -----------------------------------------------------------------
    setBlock(4, 6, 5, withState(woodLog, { axis: "x" }));
    setBlock(4, 6, 4, withState(woodStripped, { axis: "z" }));
    setBlock(4, 6, 3, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 2, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 1, withState(woodStairs, { facing: "north", half: "top" }));

    setBlock(3, 6, 3, withState(woodLog, { axis: "y" }));
    setBlock(5, 6, 3, withState(woodLog, { axis: "y" }));
    setBlock(2, 6, 2, withState(woodStairs, { facing: "east", half: "bottom" }));
    setBlock(1, 6, 2, woodFence);
    setBlock(0, 6, 3, woodFence);
    setBlock(6, 6, 2, withState(woodStairs, { facing: "west", half: "bottom" }));
    setBlock(7, 6, 2, woodFence);
    setBlock(8, 6, 3, woodFence);

    // Heavy siege projectile
    setBlock(4, 7, 2, stonePrimary);
    setBlock(4, 7, 1, "minecraft:iron_bars");

    // Loading Gantry Crane (x = 2..6, z = 6, y = 5..8)
    setBlock(2, 5, 6, withState(woodLog, { axis: "y" }));
    setBlock(2, 6, 6, withState(woodLog, { axis: "y" }));
    setBlock(2, 7, 6, withState(woodLog, { axis: "y" }));
    setBlock(2, 8, 6, withState(woodLog, { axis: "y" }));

    setBlock(6, 5, 6, withState(woodLog, { axis: "y" }));
    setBlock(6, 6, 6, withState(woodLog, { axis: "y" }));
    setBlock(6, 7, 6, withState(woodLog, { axis: "y" }));
    setBlock(6, 8, 6, withState(woodLog, { axis: "y" }));

    for (let x = 2; x <= 6; x++) {
      setBlock(x, 8, 6, withState(woodLog, { axis: "x" }));
    }
    setBlock(4, 7, 6, "minecraft:chain[axis=y]");
    setBlock(4, 6, 6, "minecraft:grindstone[face=ceiling,facing=north]");

    // Props: Supply chests & brazier
    setBlock(2, 5, 3, "minecraft:chest[facing=east]");
    setBlock(6, 5, 3, "minecraft:barrel[facing=up]");
    setBlock(7, 5, 6, "minecraft:campfire[facing=north,lit=true]");

  } else if (variant === 4) {
    // -----------------------------------------------------------------
    // VARIANT 4: "IRONCLAD SIEGE ARBALEST"
    // Armored bow prods, reinforced mantlet shutters, oil kettles
    // -----------------------------------------------------------------
    setBlock(4, 6, 5, withState(woodLog, { axis: "x" }));
    setBlock(3, 6, 5, "minecraft:grindstone[face=floor,facing=west]");
    setBlock(5, 6, 5, "minecraft:grindstone[face=floor,facing=east]");
    setBlock(4, 6, 4, withState(woodStripped, { axis: "z" }));
    setBlock(4, 6, 3, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 2, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 1, withState(woodStairs, { facing: "north", half: "top" }));

    // Armored torsion towers capped with lanterns
    setBlock(3, 6, 2, withState(woodLog, { axis: "y" }));
    setBlock(5, 6, 2, withState(woodLog, { axis: "y" }));
    setBlock(3, 7, 2, stoneWall);
    setBlock(5, 7, 2, stoneWall);
    setBlock(3, 8, 2, "minecraft:lantern[hanging=false]");
    setBlock(5, 8, 2, "minecraft:lantern[hanging=false]");

    // Chain-wrapped prods
    setBlock(2, 6, 2, "minecraft:chain[axis=x]");
    setBlock(1, 6, 2, "minecraft:chain[axis=x]");
    setBlock(0, 6, 2, "minecraft:iron_bars");
    setBlock(6, 6, 2, "minecraft:chain[axis=x]");
    setBlock(7, 6, 2, "minecraft:chain[axis=x]");
    setBlock(8, 6, 2, "minecraft:iron_bars");

    // Steel bolt
    setBlock(4, 7, 3, "minecraft:chain[axis=z]");
    setBlock(4, 7, 2, woodFence);
    setBlock(4, 7, 1, "minecraft:iron_bars");
    setBlock(4, 7, 0, "minecraft:lightning_rod[facing=north]");

    // Props: Pitch cauldron, oil barrels, brazier
    setBlock(2, 5, 6, "minecraft:barrel[facing=up]");
    setBlock(3, 5, 6, "minecraft:cauldron");
    setBlock(6, 5, 5, stoneWall);
    setBlock(6, 6, 5, "minecraft:campfire[facing=north,lit=true]");

  } else {
    // -----------------------------------------------------------------
    // VARIANT 5: "RIVER WATCH BATTERY & BEACON"
    // Fired state/reloading, tall river signal beacon tower on corner
    // -----------------------------------------------------------------
    setBlock(4, 6, 5, withState(woodLog, { axis: "x" }));
    setBlock(3, 6, 5, "minecraft:grindstone[face=floor,facing=west]");
    setBlock(5, 6, 5, "minecraft:grindstone[face=floor,facing=east]");
    setBlock(4, 6, 4, withState(woodStripped, { axis: "z" }));
    setBlock(4, 6, 3, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 2, withState(woodLog, { axis: "z" }));
    setBlock(4, 6, 1, withState(woodStairs, { facing: "north", half: "top" }));

    setBlock(3, 6, 2, withState(woodLog, { axis: "y" }));
    setBlock(5, 6, 2, withState(woodLog, { axis: "y" }));

    // Prods straight forward in fired position
    setBlock(2, 6, 2, withState(woodStairs, { facing: "east", half: "bottom" }));
    setBlock(1, 6, 1, woodFence);
    setBlock(0, 6, 1, woodFence);
    setBlock(6, 6, 2, withState(woodStairs, { facing: "west", half: "bottom" }));
    setBlock(7, 6, 1, woodFence);
    setBlock(8, 6, 1, woodFence);

    // Released straight bowstring across front
    for (let x = 0; x <= 8; x++) {
      if (x !== 4) {
        setBlock(x, 6, 1, (x === 0 || x === 8) ? woodFence : "minecraft:chain[axis=x]");
      }
    }

    // Fresh bolt being carried up from rack
    setBlock(3, 6, 4, woodFence);

    // Tall River Signal Beacon (x = 1, z = 1, y = 5..10)
    for (let y = 7; y <= 9; y++) {
      setBlock(1, y, 1, woodFence);
    }
    setBlock(1, 10, 1, "minecraft:campfire[facing=north,lit=true]");
    setBlock(1, 10, 2, "minecraft:iron_bars");
    setBlock(2, 10, 1, "minecraft:iron_bars");

    // Props: Ammo chest, spare pitch barrel
    setBlock(6, 5, 4, "minecraft:chest[facing=north]");
    setBlock(6, 5, 5, "minecraft:barrel[facing=up]");
    setBlock(7, 5, 4, woodPlanks);
    setBlock(6, 5, 6, "minecraft:campfire[facing=north,lit=true]");
  }

  return {
    name: "river_ballista",
    seatY: seatY,
    anchors: {
      front: [4, deckY + 1, 0],
      road: [4, deckY - 1, 8],
      platform: [4, deckY + 1, 4]
    }
  };
}
